using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Web.UI;
using System.Web.UI.WebControls;
using System.Data;
using System.IO;
using DCore;
using Newtonsoft.Json;

namespace InformationWeb.Controls.SimsMember
{
    public partial class MainLogin : System.Web.UI.UserControl
    {
        #region Events

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                LoadNewsData();
            }
        }

        #endregion

        #region Support Functions

        /// <summary>
        /// Nạp danh sách tin tức - thông báo
        /// </summary>
        private void LoadNewsData()
        {
            DataTable dtbNews = GetNewsData();

            if (dtbNews != null && dtbNews.Rows.Count > 0)
            {
                rptNews.DataSource = dtbNews;
                rptNews.DataBind();
            }
        }

        /// <summary>
        /// Lấy dữ liệu tin tức
        /// </summary>
        private DataTable GetNewsData()
        {
            DataTable dtb = new DataTable();
            dtb.Columns.Add("Image", typeof(string));
            dtb.Columns.Add("Day", typeof(string));
            dtb.Columns.Add("Month", typeof(string));
            dtb.Columns.Add("Category", typeof(string));
            dtb.Columns.Add("Title", typeof(string));
            dtb.Columns.Add("SubTitle", typeof(string));
            dtb.Columns.Add("Description", typeof(string));
            dtb.Columns.Add("Date", typeof(string));
            dtb.Columns.Add("Author", typeof(string));
            dtb.Columns.Add("Link", typeof(string));

            try
            {
                // Load từ file JSON trong App_Data
                string strFilePath = Server.MapPath("~/App_Data/news.json");

                if (File.Exists(strFilePath))
                {
                    string strJson = File.ReadAllText(strFilePath);
                    dtb = JsonConvert.DeserializeObject<DataTable>(strJson);
                }
            }
            catch (Exception ex)
            {
                // Log lỗi nếu cần
                // Nếu file JSON lỗi thì trả về DataTable rỗng
            }

            return dtb;
        }

        #endregion
    }
}
